import sys

def merge_the_tools(s, k):
    for i in range(0, len(s), k):
        t = s[i:i+k]
        u = []
        for char in t:
            if char not in u:
                u.append(char)
        print(''.join(u))

input = sys.stdin.read().split()
s = input[0]
k = int(input[1])
merge_the_tools(s, k)
